<div class="section-heading"><div><h2><?= e(t('Saved views')) ?></h2><p class="muted"><?= e(t('Keep a useful combination of filters and layout one click away.')) ?></p></div></div><?php if(!$views): ?><section class="card empty"><h3><?= e(t('Your workflow, your view.')) ?></h3><p><?= e(t('Save a board for a cycle, a high-priority list, or an assignee’s work.')) ?></p></section><?php else: ?><div class="website-grid"><?php foreach($views as $view): ?><article class="card"><span class="website-kicker"><?= e(WorkService::LAYOUTS[$view['layout']]) ?></span><h2><?= e($view['name']) ?></h2><div class="hero-actions"><a class="btn secondary" href="<?= $workPath ?>?view_id=<?= e($view['id']) ?>"><?= e(t('Open view')) ?></a><form method="post" action="<?= $workPath ?>/view/<?= e($view['id']) ?>/remove" data-confirm="Remove this saved view? Work items will be kept."><?= csrf_field() ?><button class="quiet"><?= e(t('Remove')) ?></button></form></div><details><summary><?= e(t('Edit view')) ?></summary><?php $viewEditing=$view;require __DIR__.'/view-form.php'; ?></details></article><?php endforeach; ?></div><?php endif; ?>
<section class="card"><h2><?= e(t('Create a saved view')) ?></h2><?php $viewEditing=null;require __DIR__.'/view-form.php'; ?></section>
